const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Lake Winnipeg geometry
  const lakeWinnipeg = ee.Geometry.Polygon([
    [[-101.5, 50.5], [-95.0, 50.5], [-95.0, 49.0], [-101.5, 49.0], [-101.5, 50.5]]
  ]);

  // Define dates
  const date1 = '2021-05-07';
  const date2 = '2021-05-19';

  // Sentinel-2 collection with cloud masking
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeWinnipeg)
    .filterDate(date1, '2021-05-08')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const s2_2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeWinnipeg)
    .filterDate(date2, '2021-05-20')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const count1 = s2.size().getInfo();
  const count2 = s2_2.size().getInfo();

  print(`May 7, 2021 Images: ${count1}`);
  print(`May 19, 2021 Images: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    print('Insufficient data for one or both dates');
    print('C1');
    return;
  }

  // Use median composite for each date
  const img1 = s2.median();
  const img2 = s2_2.median();

  // Calculate NDSI for ice detection: (Green - SWIR) / (Green + SWIR)
  // Sentinel-2: B3=Green(560nm), B11=SWIR(1610nm)
  const ndsi1 = img1.normalizedDifference(['B3', 'B11']).rename('ndsi');
  const ndsi2 = img2.normalizedDifference(['B3', 'B11']).rename('ndsi');

  // Ice threshold (NDSI > 0.4 indicates ice/snow)
  const iceThreshold = 0.4;
  const ice1 = ndsi1.gt(iceThreshold);
  const ice2 = ndsi2.gt(iceThreshold);

  // Count ice pixels
  const iceCount1 = ice1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeWinnipeg,
    scale: 1000,
    maxPixels: 1e9
  }).get('ndsi').getInfo();

  const iceCount2 = ice2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeWinnipeg,
    scale: 1000,
    maxPixels: 1e9
  }).get('ndsi').getInfo();

  print(`May 7 Ice Pixels: ${iceCount1}`);
  print(`May 19 Ice Pixels: ${iceCount2}`);

  if (iceCount1 === null || iceCount2 === null || iceCount1 === 0 && iceCount2 === 0) {
    print('No valid ice data after processing');
    print('C2');
    return;
  }

  // Calculate percentage change
  const percentChange = ((iceCount2 - iceCount1) / iceCount1 * 100);
  print(`Ice Extent Change: ${percentChange.toFixed(1)}%`);

  // Determine answer
  if (iceCount2 < iceCount1) {
    print('Ice extent decreased between May 7 and May 19, 2021');
    print('A');
  } else {
    print('Ice extent did not decrease');
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
